   366  template <typename TYPE>
   367  struct Charset1_2 {
   368    inline bool sanitize (hb_sanitize_context_t *c, unsigned int num_glyphs) const
   369    {
   370      TRACE_SANITIZE (this);
   371      if (unlikely (!c->check_struct (this)))
   372        return_trace (false);
   373      num_glyphs--;
   374      for (unsigned int i = 0; num_glyphs > 0; i++)
   375      {
   376        if (unlikely (!ranges[i].sanitize (c) || (num_glyphs < ranges[i].nLeft + 1)))
   377          return_trace (false);
   378        num_glyphs -= (ranges[i].nLeft + 1);
   379      }
   380      return_trace (true);
   381    }
   382
   383    inline hb_codepoint_t get_sid (hb_codepoint_t glyph) const
   384    {
   385      if (glyph == 0) return 0;
   386      glyph--;
   387      for (unsigned int i = 0;; i++)
   388      {
   389        if (glyph <= ranges[i].nLeft)
   390          return (hb_codepoint_t)ranges[i].first + glyph;
   391        glyph -= (ranges[i].nLeft + 1);
   392      }
   393
   394      return 0;
   395    }
   396
   397    inline hb_codepoint_t get_glyph (hb_codepoint_t sid, unsigned int num_glyphs) const
   398    {
   399      if (sid == 0) return 0;
   400      hb_codepoint_t  glyph = 1;
   401      for (unsigned int i = 0;; i++)
   402      {
   403        if (glyph >= num_glyphs)
   404          return 0;
   405        if ((ranges[i].first <= sid) && (sid <= ranges[i].first + ranges[i].nLeft))
   406          return glyph + (sid - ranges[i].first);
   407        glyph += (ranges[i].nLeft + 1);
   408      }
   409
   410      return 0;
   411    }
   412
   413    inline unsigned int get_size (unsigned int num_glyphs) const
   414    {
   415      unsigned int size = HBUINT8::static_size;
   416      int glyph = (int)num_glyphs;
   417
   418      assert (glyph > 0);
   419      glyph--;
   420      for (unsigned int i = 0; glyph > 0; i++)
   421      {
   422        glyph -= (ranges[i].nLeft + 1);
   423        size += Charset_Range<TYPE>::static_size;
   424      }
   425
   426      return size;
   427    }
   428
   429    Charset_Range<TYPE>   ranges[VAR];
   430
   431    DEFINE_SIZE_ARRAY (0, ranges);
   432  };
