   727  struct CFF1TopDictOpSet : TopDictOpSet<CFF1TopDictVal>
   728  {
   729    static inline void process_op (OpCode op, CFF1TopDictInterpEnv& env, CFF1TopDictValues& dictval)
   730    {
   731      CFF1TopDictVal  val;
   732      val.last_arg_offset = (env.last_offset-1) - dictval.opStart;  /* offset to the last argument */
   733
   734      switch (op) {
   735        case OpCode_version:
   736        case OpCode_Notice:
   737        case OpCode_Copyright:
   738        case OpCode_FullName:
   739        case OpCode_FamilyName:
   740        case OpCode_Weight:
   741        case OpCode_PostScript:
   742        case OpCode_BaseFontName:
   743          dictval.nameSIDs[NameDictValues::name_op_to_index (op)] = env.argStack.pop_uint ();
   744          env.clear_args ();
   745          break;
   746        case OpCode_isFixedPitch:
   747        case OpCode_ItalicAngle:
   748        case OpCode_UnderlinePosition:
   749        case OpCode_UnderlineThickness:
   750        case OpCode_PaintType:
   751        case OpCode_CharstringType:
   752        case OpCode_UniqueID:
   753        case OpCode_StrokeWidth:
   754        case OpCode_SyntheticBase:
   755        case OpCode_CIDFontVersion:
   756        case OpCode_CIDFontRevision:
   757        case OpCode_CIDFontType:
   758        case OpCode_UIDBase:
   759        case OpCode_FontBBox:
   760        case OpCode_XUID:

760        case OpCode_XUID:
   761        case OpCode_BaseFontBlend:
   762          env.clear_args ();
   763          break;
   764
   765        case OpCode_CIDCount:
   766          dictval.cidCount = env.argStack.pop_uint ();
   767          env.clear_args ();
   768          break;
   769
   770        case OpCode_ROS:
   771          dictval.ros_supplement = env.argStack.pop_uint ();
   772          dictval.nameSIDs[NameDictValues::ordering] = env.argStack.pop_uint ();
   773          dictval.nameSIDs[NameDictValues::registry] = env.argStack.pop_uint ();
   774          env.clear_args ();
   775          break;
   776
   777        case OpCode_Encoding:
   778          dictval.EncodingOffset = env.argStack.pop_uint ();
   779          env.clear_args ();
   780          if (unlikely (dictval.EncodingOffset == 0)) return;
   781          break;
   782
   783        case OpCode_charset:
   784          dictval.CharsetOffset = env.argStack.pop_uint ();
   785          env.clear_args ();
   786          if (unlikely (dictval.CharsetOffset == 0)) return;
   787          break;
   788
   789        case OpCode_FDSelect:
   790          dictval.FDSelectOffset = env.argStack.pop_uint ();
   791          env.clear_args ();
   792          break;
   793
   794        case OpCode_Private:
   795          dictval.privateDictInfo.offset = env.argStack.pop_uint ();
   796          dictval.privateDictInfo.size = env.argStack.pop_uint ();
   797          env.clear_args ();
   798          break;
   799
   800        default:
   801          env.last_offset = env.substr.offset;
   802          TopDictOpSet<CFF1TopDictVal>::process_op (op, env, dictval);
   803          /* Record this operand below if stack is empty, otherwise done */
   804          if (!env.argStack.is_empty ()) return;
   805          break;
   806      }
   807
   808      if (unlikely (env.in_error ())) return;
   809
   810      dictval.add_op (op, env.substr, val);
   811    }
   812  };
