   845        case OpCode_Private:
   846          dictval.privateDictInfo.offset = env.argStack.pop_uint ();
   847          dictval.privateDictInfo.size = env.argStack.pop_uint ();
   848          env.clear_args ();
   849          break;
   850
   851        default:
   852          DictOpSet::process_op (op, env);
   853          if (!env.argStack.is_empty ()) return;
   854          break;
   855      }
   856
   857      if (unlikely (env.in_error ())) return;
   858
   859      dictval.add_op (op, env.substr);
   860    }
