  1009    template <typename PRIVOPSET, typename PRIVDICTVAL>
  1010    struct accelerator_templ_t
  1011    {
  1012      inline void init (hb_face_t *face)
  1013      {
  1014        topDict.init ();
  1015        fontDicts.init ();
  1016        privateDicts.init ();
  1017
  1018        this->blob = sc.reference_table<cff1> (face);
  1019
  1020        /* setup for run-time santization */
  1021        sc.init (this->blob);
  1022        sc.start_processing ();
  1023
  1024        const OT::cff1 *cff = this->blob->template as<OT::cff1> ();
  1025
  1026        if (cff == &Null(OT::cff1))
  1027        { fini (); return; }
  1028
  1029        nameIndex = &cff->nameIndex (cff);
  1030        if ((nameIndex == &Null (CFF1NameIndex)) || !nameIndex->sanitize (&sc))
  1031        { fini (); return; }
  1032
  1033        topDictIndex = &StructAtOffset<CFF1TopDictIndex> (nameIndex, nameIndex->get_size ());
  1034        if ((topDictIndex == &Null (CFF1TopDictIndex)) || !topDictIndex->sanitize (&sc) || (topDictIndex->count == 0))
  1035        { fini (); return; }
  1036
  1037        { /* parse top dict */
  1038          const ByteStr topDictStr = (*topDictIndex)[0];
  1039          if (unlikely (!topDictStr.sanitize (&sc))) { fini (); return; }
  1040          CFF1TopDict_Interpreter top_interp;
  1041          top_interp.env.init (topDictStr);
  1042          topDict.init ();
  1043          if (unlikely (!top_interp.interpret (topDict))) { fini (); return; }
  1044        }
  1045
  1046        if (is_predef_charset ())
  1047          charset = &Null(Charset);
  1048        else
  1049        {
  1050          charset = &StructAtOffsetOrNull<Charset> (cff, topDict.CharsetOffset);
  1051          if (unlikely ((charset == &Null (Charset)) || !charset->sanitize (&sc))) { fini (); return; }
  1052        }
  1053
  1054        fdCount = 1;
  1055        if (is_CID ())
  1056        {
  1057          fdArray = &StructAtOffsetOrNull<CFF1FDArray> (cff, topDict.FDArrayOffset);
  1058          fdSelect = &StructAtOffsetOrNull<CFF1FDSelect> (cff, topDict.FDSelectOffset);
  1059          if (unlikely ((fdArray == &Null(CFF1FDArray)) || !fdArray->sanitize (&sc) ||
  1060              (fdSelect == &Null(CFF1FDSelect)) || !fdSelect->sanitize (&sc, fdArray->count)))
  1061          { fini (); return; }
  1062
  1063          fdCount = fdArray->count;
  1064        }
  1065        else
  1066        {
  1067          fdArray = &Null(CFF1FDArray);
  1068          fdSelect = &Null(CFF1FDSelect);
  1069        }
  1070
  1071        stringIndex = &StructAtOffset<CFF1StringIndex> (topDictIndex, topDictIndex->get_size ());
  1072        if ((stringIndex == &Null (CFF1StringIndex)) || !stringIndex->sanitize (&sc))
  1073        { fini (); return; }
  1074
  1075        globalSubrs = &StructAtOffset<CFF1Subrs> (stringIndex, stringIndex->get_size ());
  1076        if ((globalSubrs != &Null (CFF1Subrs)) && !globalSubrs->sanitize (&sc))
  1077        { fini (); return; }
  1078
  1079        charStrings = &StructAtOffsetOrNull<CFF1CharStrings> (cff, topDict.charStringsOffset);
  1080
  1081        if ((charStrings == &Null(CFF1CharStrings)) || unlikely (!charStrings->sanitize (&sc)))
  1082        { fini (); return; }
  1083
  1084        num_glyphs = charStrings->count;
  1085        if (num_glyphs != sc.get_num_glyphs ())
  1086        { fini (); return; }
  1087
  1088        privateDicts.resize (fdCount);
  1089        for (unsigned int i = 0; i < fdCount; i++)
  1090          privateDicts[i].init ();
  1091
  1092        // parse CID font dicts and gather private dicts
  1093        if (is_CID ())
  1094        {
  1095          for (unsigned int i = 0; i < fdCount; i++)
  1096          {
  1097            ByteStr fontDictStr = (*fdArray)[i];
  1098            if (unlikely (!fontDictStr.sanitize (&sc))) { fini (); return; }
  1099            CFF1FontDictValues  *font;
  1100            CFF1FontDict_Interpreter font_interp;
  1101            font_interp.env.init (fontDictStr);
  1102            font = fontDicts.push ();
  1103            if (unlikely (font == &Crap(CFF1FontDictValues))) { fini (); return; }
  1104            font->init ();
  1105            if (unlikely (!font_interp.interpret (*font))) { fini (); return; }
  1106            PRIVDICTVAL  *priv = &privateDicts[i];
  1107            const ByteStr privDictStr (StructAtOffset<UnsizedByteStr> (cff, font->privateDictInfo.offset), font->privateDictInfo.size);
  1108            if (unlikely (!privDictStr.sanitize (&sc))) { fini (); return; }
  1109            DictInterpreter<PRIVOPSET, PRIVDICTVAL> priv_interp;
  1110            priv_interp.env.init (privDictStr);
  1111            priv->init ();
  1112            if (unlikely (!priv_interp.interpret (*priv))) { fini (); return; }
  1113
  1114            priv->localSubrs = &StructAtOffsetOrNull<CFF1Subrs> (privDictStr.str, priv->subrsOffset);
  1115            if (priv->localSubrs != &Null(CFF1Subrs) &&
  1116                unlikely (!priv->localSubrs->sanitize (&sc)))
  1117            { fini (); return; }
  1118          }
  1119        }
  1120        else  /* non-CID */
  1121        {
  1122          CFF1TopDictValues  *font = &topDict;
  1123          PRIVDICTVAL  *priv = &privateDicts[0];
  1124
  1125          const ByteStr privDictStr (StructAtOffset<UnsizedByteStr> (cff, font->privateDictInfo.offset), font->privateDictInfo.size);
  1126          if (unlikely (!privDictStr.sanitize (&sc))) { fini (); return; }
  1127          DictInterpreter<PRIVOPSET, PRIVDICTVAL> priv_interp;
  1128          priv_interp.env.init (privDictStr);
  1129          priv->init ();
  1130          if (unlikely (!priv_interp.interpret (*priv))) { fini (); return; }
  1131
  1132          priv->localSubrs = &StructAtOffsetOrNull<CFF1Subrs> (privDictStr.str, priv->subrsOffset);
  1133          if (priv->localSubrs != &Null(CFF1Subrs) &&
  1134              unlikely (!priv->localSubrs->sanitize (&sc)))
  1135          { fini (); return; }
  1136        }
  1137      }
  1138
  1139      inline void fini (void)
  1140      {
  1141        sc.end_processing ();
  1142        topDict.fini ();
  1143        fontDicts.fini_deep ();
  1144        privateDicts.fini_deep ();
  1145        hb_blob_destroy (blob);
  1146        blob = nullptr;
  1147      }
  1148
  1149      inline bool is_valid (void) const { return blob != nullptr; }
  1150      inline bool is_CID (void) const { return topDict.is_CID (); }
  1151
  1152      inline bool is_predef_charset (void) const { return topDict.CharsetOffset <= ExpertSubsetCharset; }
  1153
  1154      inline unsigned int  std_code_to_glyph (hb_codepoint_t code) const
  1155      {
  1156        hb_codepoint_t sid = lookup_standard_encoding_for_sid (code);
  1157        if (unlikely (sid == CFF_UNDEF_SID))
  1158          return 0;
  1159
  1160        if (charset != &Null(Charset))
  1161          return charset->get_glyph (sid, num_glyphs);
  1162        else if ((topDict.CharsetOffset == ISOAdobeCharset)
  1163                && (code <= 228 /*zcaron*/)) return sid;
  1164        return 0;
  1165      }
  1166
  1167      protected:
  1168      hb_blob_t          *blob;
  1169      hb_sanitize_context_t   sc;
  1170
  1171      public:
  1172      const Charset          *charset;
  1173      const CFF1NameIndex     *nameIndex;
  1174      const CFF1TopDictIndex  *topDictIndex;
  1175      const CFF1StringIndex   *stringIndex;
  1176      const CFF1Subrs      *globalSubrs;
  1177      const CFF1CharStrings   *charStrings;
  1178      const CFF1FDArray       *fdArray;
  1179      const CFF1FDSelect      *fdSelect;
  1180      unsigned int            fdCount;
  1181
  1182      CFF1TopDictValues       topDict;
  1183      hb_vector_t<CFF1FontDictValues>   fontDicts;
  1184      hb_vector_t<PRIVDICTVAL>      privateDicts;
  1185
  1186      unsigned int            num_glyphs;
  1187    };
