  1195    struct accelerator_subset_t : accelerator_templ_t<CFF1PrivateDictOpSet_Subset, CFF1PrivateDictValues_Subset>
   560        size_ranges = Charset1::min_size + Charset1_Range::static_size * subset_charset_ranges.len;
   561      else
